#define DM_VER "0.1.0"

#define C_BG     0x000000
#define C_FACE   0xFFFFFF
#define C_EYE    0x000000
#define C_INK    0xFFFFFF
#define C_MUTED  0x666666
#define C_DIM    0x888888
#define C_BTN    0x111111
#define C_BTN_HI 0x222222
#define C_STAR   0xFFD54F
