/****************************************************************************
 * deskmate_main.c — entry & LVGL bring-up
 ****************************************************************************/

#include "deskmate.h"
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/boardctl.h>

#ifdef CONFIG_DESKMATE_APP

#ifndef NEED_BOARDINIT
#  if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#    define NEED_BOARDINIT 1
#  endif
#endif

static void tick_cb(lv_timer_t *t)
{
  (void)t;
  dm_tick();
}

int deskmate_main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  (void)argc;
  (void)argv;

  if (lv_is_initialized())
    {
      return -1;
    }

#ifdef CONFIG_SYSTEM_SYSTEM
  (void)system("killall luncher_mini > /dev/null 2>&1");
#endif

#ifdef NEED_BOARDINIT
  boardctl(BOARDIOC_INIT, 0);
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH
  info.input_path = CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH;
#endif
  lv_nuttx_init(&info, &result);
  usleep(100000);
  if (!result.disp)
    {
      return 1;
    }

  dm_init_fonts();

  g_dm_root = lv_obj_create(lv_screen_active());
  lv_obj_set_size(g_dm_root, DM_SCR_W, DM_SCR_H);
  lv_obj_center(g_dm_root);
  lv_obj_set_style_bg_color(g_dm_root, lv_color_hex(C_BG), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_root, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(g_dm_root, 0, LV_PART_MAIN);
  lv_obj_set_style_radius(g_dm_root, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(g_dm_root, 0, LV_PART_MAIN);
  lv_obj_clear_flag(g_dm_root, LV_OBJ_FLAG_SCROLLABLE);

  dm_create_focus_home();
  dm_create_focus_run();
  dm_create_chat();
  dm_create_health();
  dm_create_supervise();
  dm_create_note();
  dm_create_dock();
  dm_show(PAGE_FOCUS_HOME);

  lv_timer_create(tick_cb, 250, NULL);

  LV_LOG_USER("Deskmate %s focus-home zh=%d", DM_VER, (int)g_dm.zh);

  while (true)
    {
      uint32_t idle = lv_timer_handler();
      usleep(idle ? idle * 1000 : 5000);
    }

  return 0;
}

#endif /* CONFIG_DESKMATE_APP */

/****************************************************************************
 * dm_state.c — fonts, navigation, shared helpers
 ****************************************************************************/

#include "deskmate.h"
#include <string.h>
#include <stdio.h>

#ifdef CONFIG_DESKMATE_APP

dm_ctx_t g_dm = {
  .page = PAGE_FOCUS_HOME,
  .face = FACE_IDLE,
  .decor = EYE_DECOR_NONE,
  .focus_left = 25 * 60,
  .focus_total = 25 * 60,
  .focus_sel_min = 25,
  .focus_custom_min = 30,
  .focus_run = false,
  .focus_finished = false,
  .zh = true,
};

const lv_font_t *g_dm_font_s;
const lv_font_t *g_dm_font_m;
const lv_font_t *g_dm_font_l;
const lv_font_t *g_dm_font_xl;

lv_obj_t *g_dm_root;
lv_obj_t *g_dm_pages[PAGE_COUNT];
lv_obj_t *g_dm_dock;
lv_obj_t *g_dm_face;
lv_obj_t *g_dm_bubble;
lv_obj_t *g_dm_eye_l;
lv_obj_t *g_dm_eye_r;
lv_obj_t *g_dm_mouth;
lv_obj_t *g_dm_decor_l;
lv_obj_t *g_dm_decor_r;

const char *dm_t(const char *zh, const char *en)
{
  return g_dm.zh ? zh : en;
}

void dm_style(lv_obj_t *o, const lv_font_t *f, uint32_t c)
{
  lv_obj_set_style_text_font(o, f, LV_PART_MAIN);
  lv_obj_set_style_text_color(o, lv_color_hex(c), LV_PART_MAIN);
}

lv_obj_t *dm_lbl(lv_obj_t *p, const char *zh, const char *en,
                 const lv_font_t *f, uint32_t c)
{
  lv_obj_t *o = lv_label_create(p);
  lv_label_set_text(o, dm_t(zh, en));
  dm_style(o, f, c);
  return o;
}

lv_obj_t *dm_btn(lv_obj_t *p, const char *zh, const char *en, int w, int h,
                 uint32_t bg, uint32_t fg, lv_event_cb_t cb, void *ud)
{
  lv_obj_t *b = lv_button_create(p);
  lv_obj_remove_style_all(b);
  lv_obj_set_size(b, w, h);
  lv_obj_set_style_radius(b, h / 2, LV_PART_MAIN);
  lv_obj_set_style_bg_color(b, lv_color_hex(bg), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_add_flag(b, LV_OBJ_FLAG_CLICKABLE);
  if (cb)
    {
      lv_obj_add_event_cb(b, cb, LV_EVENT_CLICKED, ud);
    }

  lv_obj_t *t = dm_lbl(b, zh, en, g_dm_font_s, fg);
  lv_obj_center(t);
  return b;
}

void dm_say(const char *zh, const char *en)
{
  if (g_dm_bubble)
    {
      lv_label_set_text(g_dm_bubble, dm_t(zh, en));
    }
}

static const lv_font_t *try_ft(const char *path, uint16_t sz)
{
#ifdef LV_USE_FREETYPE
  return lv_freetype_font_create(path, LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                 sz, LV_FREETYPE_FONT_STYLE_NORMAL);
#else
  (void)path;
  (void)sz;
  return NULL;
#endif
}

void dm_init_fonts(void)
{
  const char *paths[] = {
    "/data/font/MiSans-Regular.ttf",
    "/resource/fonts/MiSans-Normal.ttf",
    "/resource/fonts/MiSans-Regular.ttf",
  };
  int i;

  g_dm_font_s = NULL;
  g_dm_font_m = NULL;
  g_dm_font_l = NULL;
  g_dm_font_xl = NULL;

  for (i = 0; i < 3 && !g_dm_font_s; i++)
    {
      g_dm_font_s = try_ft(paths[i], 12);
      if (g_dm_font_s)
        {
          g_dm_font_m = try_ft(paths[i], 16);
          g_dm_font_l = try_ft(paths[i], 20);
          g_dm_font_xl = try_ft(paths[i], 42);
        }
    }

  if (!g_dm_font_s)
    {
      g_dm_font_s = &lv_font_montserrat_12;
      g_dm_font_m = &lv_font_montserrat_16;
      g_dm_font_l = &lv_font_montserrat_20;
      g_dm_font_xl = &lv_font_montserrat_48;
    }
  if (!g_dm_font_m)
    {
      g_dm_font_m = &lv_font_montserrat_16;
    }
  if (!g_dm_font_l)
    {
      g_dm_font_l = &lv_font_montserrat_20;
    }
  if (!g_dm_font_xl)
    {
      g_dm_font_xl = &lv_font_montserrat_48;
    }
}

static void fade_in(lv_obj_t *page)
{
  lv_anim_t a;
  lv_obj_clear_flag(page, LV_OBJ_FLAG_HIDDEN);
  lv_obj_set_style_opa(page, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_anim_init(&a);
  lv_anim_set_var(&a, page);
  lv_anim_set_values(&a, LV_OPA_TRANSP, LV_OPA_COVER);
  lv_anim_set_time(&a, 320);
  lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_style_opa);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  lv_anim_start(&a);
}

void dm_show(dm_page_t p)
{
  int i;

  if (p >= PAGE_COUNT)
    {
      return;
    }

  g_dm.page = p;
  for (i = 0; i < PAGE_COUNT; i++)
    {
      if (!g_dm_pages[i])
        {
          continue;
        }

      if (i == (int)p)
        {
          fade_in(g_dm_pages[i]);
        }
      else
        {
          lv_obj_add_flag(g_dm_pages[i], LV_OBJ_FLAG_HIDDEN);
        }
    }

  if (g_dm_dock)
    {
      if (p == PAGE_FOCUS_RUN)
        {
          lv_obj_add_flag(g_dm_dock, LV_OBJ_FLAG_HIDDEN);
        }
      else
        {
          lv_obj_clear_flag(g_dm_dock, LV_OBJ_FLAG_HIDDEN);
        }
    }

  if (p != PAGE_FOCUS_RUN && g_dm.focus_run)
    {
      /* keep countdown running in background, but face idles on other pages */
      dm_face_set(FACE_IDLE, EYE_DECOR_NONE, 0);
    }
}

void dm_tick(void)
{
  dm_face_tick();
  dm_focus_run_tick();
}

#endif /* CONFIG_DESKMATE_APP */

/****************************************************************************
 * dm_face.c — geometric face, blink, star/heart/wide eyes
 ****************************************************************************/

#include "deskmate.h"

#ifdef CONFIG_DESKMATE_APP

static int s_blink_ph; /* 0 open, 1 half, 2 shut */
static int s_blink_hold;
static int s_blink_gap = 8;
static int s_idle_t;
static dm_face_t s_paint_face = FACE_IDLE;

static void mk_soft(lv_obj_t *parent, lv_obj_t **out, uint32_t col, int w,
                    int h)
{
  lv_obj_t *o = lv_obj_create(parent);
  lv_obj_set_size(o, w, h);
  lv_obj_set_style_radius(o, 100, LV_PART_MAIN);
  lv_obj_set_style_bg_color(o, lv_color_hex(col), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(o, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_style_border_width(o, 0, LV_PART_MAIN);
  lv_obj_clear_flag(o, LV_OBJ_FLAG_SCROLLABLE);
  *out = o;
}

void dm_face_build(lv_obj_t *parent, int x, int y, int size)
{
  lv_obj_t *face = lv_obj_create(parent);
  int eye_w = size > 70 ? 12 : 10;
  int eye_h = size > 70 ? 14 : 12;

  lv_obj_set_size(face, size, size);
  lv_obj_set_pos(face, x, y);
  lv_obj_set_style_radius(face, LV_RADIUS_CIRCLE, LV_PART_MAIN);
  lv_obj_set_style_bg_color(face, lv_color_hex(C_FACE), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(face, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(face, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(face, 0, LV_PART_MAIN);
  lv_obj_clear_flag(face, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_flag(face, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_add_event_cb(face, dm_face_on_click, LV_EVENT_CLICKED, NULL);

  g_dm_face = face;

  g_dm_eye_l = lv_obj_create(face);
  lv_obj_set_size(g_dm_eye_l, eye_w, eye_h);
  lv_obj_set_style_radius(g_dm_eye_l, LV_RADIUS_CIRCLE, LV_PART_MAIN);
  lv_obj_set_style_bg_color(g_dm_eye_l, lv_color_hex(C_EYE), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_eye_l, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(g_dm_eye_l, 0, LV_PART_MAIN);
  lv_obj_clear_flag(g_dm_eye_l, LV_OBJ_FLAG_SCROLLABLE);

  g_dm_eye_r = lv_obj_create(face);
  lv_obj_set_size(g_dm_eye_r, eye_w, eye_h);
  lv_obj_set_style_radius(g_dm_eye_r, LV_RADIUS_CIRCLE, LV_PART_MAIN);
  lv_obj_set_style_bg_color(g_dm_eye_r, lv_color_hex(C_EYE), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_eye_r, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(g_dm_eye_r, 0, LV_PART_MAIN);
  lv_obj_clear_flag(g_dm_eye_r, LV_OBJ_FLAG_SCROLLABLE);

  g_dm_mouth = lv_obj_create(face);
  lv_obj_set_size(g_dm_mouth, size / 4, 4);
  lv_obj_set_style_radius(g_dm_mouth, 8, LV_PART_MAIN);
  lv_obj_set_style_bg_color(g_dm_mouth, lv_color_hex(C_EYE), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_mouth, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(g_dm_mouth, 0, LV_PART_MAIN);
  lv_obj_clear_flag(g_dm_mouth, LV_OBJ_FLAG_SCROLLABLE);

  mk_soft(face, &g_dm_decor_l, C_STAR, 10, 10);
  mk_soft(face, &g_dm_decor_r, C_STAR, 10, 10);

  s_paint_face = FACE_IDLE;
  dm_face_set(FACE_IDLE, EYE_DECOR_NONE, 0);
}

void dm_face_set(dm_face_t f, dm_eye_decor_t decor, int decor_hold)
{
  g_dm.face = f;
  g_dm.decor = decor;
  g_dm.decor_hold = decor_hold;
  if (decor == EYE_DECOR_WIDE)
    {
      g_dm.wide_hold = decor_hold;
    }
  s_paint_face = f;
}

static void paint_eyes(int size, bool wide)
{
  int base = size > 70 ? 14 : 12;
  int ew = wide ? base + 6 : base;
  int eh = wide ? base + 8 : base + 2;
  int lx = g_dm.look_x;
  int ly = g_dm.look_y;
  int mid = size / 2;
  int span = size / 4;

  if (!g_dm_eye_l || !g_dm_eye_r)
    {
      return;
    }

  if (s_blink_ph == 2)
    {
      eh = 3;
      ew = base + 8;
      lx = 0;
      ly = 0;
    }
  else if (s_blink_ph == 1)
    {
      eh = 7;
    }

  lv_obj_set_size(g_dm_eye_l, ew, eh);
  lv_obj_set_size(g_dm_eye_r, ew, eh);
  lv_obj_set_pos(g_dm_eye_l, mid - span - ew / 2 + lx, size * 30 / 100 + ly);
  lv_obj_set_pos(g_dm_eye_r, mid + span - ew / 2 - lx, size * 30 / 100 + ly);

  if (g_dm_mouth)
    {
      int mw = 16;
      int mh = 4;
      switch (s_paint_face)
        {
          case FACE_HAPPY:
          case FACE_DONE:
            mw = 22;
            mh = 5;
            break;
          case FACE_LOVE:
            mw = 18;
            mh = 4;
            break;
          case FACE_SURPRISE:
            mw = 12;
            mh = 12;
            break;
          case FACE_FOCUS:
            mw = 14;
            mh = 3;
            break;
          default:
            break;
        }

      lv_obj_set_size(g_dm_mouth, mw, mh);
      lv_obj_set_pos(g_dm_mouth, size / 2 - mw / 2, size * 62 / 100);
    }
}

static void paint_decor(int size)
{
  if (!g_dm_decor_l || !g_dm_decor_r)
    {
      return;
    }

  if (g_dm.decor == EYE_DECOR_NONE || s_blink_ph == 2)
    {
      lv_obj_set_style_bg_opa(g_dm_decor_l, LV_OPA_TRANSP, LV_PART_MAIN);
      lv_obj_set_style_bg_opa(g_dm_decor_r, LV_OPA_TRANSP, LV_PART_MAIN);
      return;
    }

  uint32_t col = C_STAR;
  int d = 8;
  if (g_dm.decor == EYE_DECOR_HEART)
    {
      col = C_HEART;
      d = 9;
    }
  else if (g_dm.decor == EYE_DECOR_WIDE)
    {
      /* highlight glints */
      col = C_ACCENT;
      d = 6;
    }

  lv_obj_set_style_bg_color(g_dm_decor_l, lv_color_hex(col), LV_PART_MAIN);
  lv_obj_set_style_bg_color(g_dm_decor_r, lv_color_hex(col), LV_PART_MAIN);
  lv_obj_set_size(g_dm_decor_l, d, d);
  lv_obj_set_size(g_dm_decor_r, d, d);
  lv_obj_set_style_bg_opa(g_dm_decor_l, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_decor_r, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_pos(g_dm_decor_l, size * 22 / 100, size * 22 / 100);
  lv_obj_set_pos(g_dm_decor_r, size * 70 / 100, size * 22 / 100);
}

static void paint(void)
{
  int size = 88;
  bool wide = g_dm.decor == EYE_DECOR_WIDE || g_dm.wide_hold > 0 ||
              s_paint_face == FACE_SURPRISE;

  if (g_dm_face)
    {
      size = lv_obj_get_width(g_dm_face);
    }

  paint_eyes(size, wide);
  paint_decor(size);
}

void dm_face_tick(void)
{
  if (!g_dm_face)
    {
      return;
    }

  s_idle_t++;

  if (s_blink_hold > 0)
    {
      s_blink_hold--;
    }
  else
    {
      if (s_blink_ph == 0)
        {
          if (s_blink_gap > 0)
            {
              s_blink_gap--;
            }
          else
            {
              s_blink_ph = 1;
              s_blink_hold = 1;
            }
        }
      else if (s_blink_ph == 1)
        {
          s_blink_ph = 2;
          s_blink_hold = 1;
        }
      else
        {
          s_blink_ph = 0;
          s_blink_hold = 0;
          s_blink_gap = 6 + (s_idle_t % 10);
        }
    }

  if (g_dm.decor_hold > 0)
    {
      g_dm.decor_hold--;
      if (g_dm.decor_hold == 0 && g_dm.page == PAGE_FOCUS_RUN)
        {
          g_dm.decor = EYE_DECOR_NONE;
        }
    }

  if (g_dm.wide_hold > 0)
    {
      g_dm.wide_hold--;
    }

  /* gentle look-around while idle / focus */
  if (s_idle_t % 6 == 0)
    {
      g_dm.look_x = ((s_idle_t / 6) % 5) - 2;
      g_dm.look_y = ((s_idle_t / 9) % 3) - 1;
    }

  /* occasional focus-run decorations */
  if (g_dm.page == PAGE_FOCUS_RUN && g_dm.focus_run && !g_dm.focus_finished)
    {
      if (g_dm.decor == EYE_DECOR_NONE && s_idle_t % 28 == 0)
        {
          int pick = (s_idle_t / 28) % 3;
          if (pick == 0)
            {
              dm_face_set(FACE_FOCUS, EYE_DECOR_STAR, 8);
              dm_say("星星眼，状态不错", "Sparkle eyes — nice pace");
            }
          else if (pick == 1)
            {
              dm_face_set(FACE_LOVE, EYE_DECOR_HEART, 8);
              dm_say("给你比个心，继续", "Heart eyes — keep going");
            }
          else
            {
              dm_face_set(FACE_SURPRISE, EYE_DECOR_WIDE, 6);
              dm_say("睁大眼睛看着你", "Watching you, stay with it");
            }
        }
    }

  paint();
}

