/****************************************************************************
 * dm_roll.c — MM:SS rolling digit clock
 ****************************************************************************/

#include "deskmate.h"
#include <stdio.h>

#ifdef CONFIG_DESKMATE_APP

static void set_label_text(lv_obj_t *lbl, int digit)
{
  char b[2] = { (char)('0' + digit), 0 };
  lv_label_set_text(lbl, b);
}

static void digit_clip_setup(dm_digit_t *d, lv_obj_t *parent, int x, int y,
                             int w, int h, const lv_font_t *font)
{
  d->clip = lv_obj_create(parent);
  lv_obj_set_size(d->clip, w, h);
  lv_obj_set_pos(d->clip, x, y);
  lv_obj_set_style_bg_opa(d->clip, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_style_border_width(d->clip, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(d->clip, 0, LV_PART_MAIN);
  lv_obj_set_style_clip_corner(d->clip, true, LV_PART_MAIN);
  lv_obj_set_style_radius(d->clip, 6, LV_PART_MAIN);
  lv_obj_clear_flag(d->clip, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_flag(d->clip, LV_OBJ_FLAG_OVERFLOW_VISIBLE); /* overridden below */
  /* force clip: hide overflow via clip_corner + fixed size */

  d->cur = lv_label_create(d->clip);
  dm_style(d->cur, font, C_INK);
  lv_obj_set_style_text_align(d->cur, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
  lv_obj_set_size(d->cur, w, h);
  lv_obj_set_style_text_line_space(d->cur, 0, LV_PART_MAIN);
  lv_obj_align(d->cur, LV_ALIGN_CENTER, 0, 0);
  d->digit = -1;
}

typedef struct {
  lv_obj_t *old;
  lv_obj_t *nw;
} roll_pair_t;

static void anim_ready_del(lv_anim_t *a)
{
  roll_pair_t *p = (roll_pair_t *)a->user_data;
  if (p)
    {
      if (p->old)
        {
          lv_obj_delete(p->old);
        }
      lv_free(p);
    }
}

static void roll_to(dm_digit_t *d, int digit, int w, int h,
                    const lv_font_t *font)
{
  lv_anim_t a;
  roll_pair_t *pair;
  lv_obj_t *nw;

  if (digit == d->digit && d->cur)
    {
      return;
    }

  pair = lv_malloc(sizeof(roll_pair_t));
  if (!pair)
    {
      set_label_text(d->cur, digit);
      d->digit = digit;
      return;
    }

  pair->old = d->cur;
  nw = lv_label_create(d->clip);
  dm_style(nw, font, C_INK);
  set_label_text(nw, digit);
  lv_obj_set_size(nw, w, h);
  lv_obj_set_style_text_align(nw, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
  lv_obj_set_pos(nw, 0, h);
  pair->nw = nw;
  d->cur = nw;
  d->digit = digit;

  if (pair->old)
    {
      lv_anim_init(&a);
      lv_anim_set_var(&a, pair->old);
      lv_anim_set_values(&a, 0, -h);
      lv_anim_set_time(&a, 160);
      lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_y);
      lv_anim_set_path_cb(&a, lv_anim_path_ease_in);
      lv_anim_set_user_data(&a, pair);
      lv_anim_set_ready_cb(&a, anim_ready_del);
      lv_anim_start(&a);
    }
  else
    {
      lv_free(pair);
    }

  lv_anim_init(&a);
  lv_anim_set_var(&a, nw);
  lv_anim_set_values(&a, h, 0);
  lv_anim_set_time(&a, 160);
  lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_y);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  lv_anim_start(&a);
}

void dm_clock_create(dm_clock_t *c, lv_obj_t *parent, int x, int y, int w,
                     int h, const lv_font_t *font)
{
  int dw = w / 5;
  int i;

  c->box = lv_obj_create(parent);
  lv_obj_set_size(c->box, w, h);
  lv_obj_set_pos(c->box, x, y);
  lv_obj_set_style_bg_opa(c->box, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_style_border_width(c->box, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(c->box, 0, LV_PART_MAIN);
  lv_obj_clear_flag(c->box, LV_OBJ_FLAG_SCROLLABLE);

  for (i = 0; i < 4; i++)
    {
      int dx = i * dw + (i >= 2 ? dw / 2 : 0);
      digit_clip_setup(&c->d[i], c->box, dx, 0, dw, h, font);
    }

  for (i = 0; i < 2; i++)
    {
      lv_obj_t *col = lv_label_create(c->box);
      lv_label_set_text(col, ":");
      dm_style(col, font, C_DIM);
      lv_obj_set_pos(col, (2 * dw) + dw / 4 + (i * dw), 0);
    }
}

void dm_clock_set(dm_clock_t *c, int32_t seconds_left)
{
  int32_t left = seconds_left < 0 ? 0 : seconds_left;
  int mm = (int)(left / 60);
  int ss = (int)(left % 60);
  int digits[4];
  int dw;
  int h;
  int i;

  if (!c->box)
    {
      return;
    }

  if (mm > 99)
    {
      mm = 99;
    }

  digits[0] = mm / 10;
  digits[1] = mm % 10;
  digits[2] = ss / 10;
  digits[3] = ss % 10;

  dw = lv_obj_get_width(c->box) / 5;
  h = lv_obj_get_height(c->box);

  for (i = 0; i < 4; i++)
    {
      roll_to(&c->d[i], digits[i], dw, h, g_dm_font_xl);
    }
}

void dm_clock_refresh_now(dm_clock_t *c)
{
  dm_clock_set(c, g_dm.focus_left);
}

