void dm_face_attach(lv_obj_t *page, int x, int y)
{
  if (!g_dm_face || !page)
    {
      return;
    }
  if (lv_obj_get_parent(g_dm_face) != page)
    {
      lv_obj_set_parent(g_dm_face, page);
    }
  lv_obj_set_pos(g_dm_face, x, y);
  lv_obj_move_foreground(g_dm_face);
}

void dm_face_set(dm_face_t f, dm_eye_decor_t decor, int decor_hold)
{
  g_dm.face = f;
  g_dm.decor = decor;
  g_dm.decor_hold = decor_hold;
  if (decor == EYE_DECOR_WIDE)
    {
      g_dm.wide_hold = decor_hold;
    }
  s_paint_face = f;
}

static void paint(void)
{
  int size = 80;
  bool wide = (g_dm.decor == EYE_DECOR_WIDE) || (g_dm.wide_hold > 0) ||
              (s_paint_face == FACE_SURPRISE);
  int base_w;
  int base_h;
  int ew;
  int eh;
  int lx = g_dm.look_x;
  int ly = g_dm.look_y;

  if (!g_dm_face)
    {
      return;
    }

  size = lv_obj_get_width(g_dm_face);
  base_w = size > 70 ? 12 : 10;
  base_h = size > 70 ? 14 : 12;
  ew = wide ? base_w + 6 : base_w;
  eh = wide ? base_h + 8 : base_h;

  if (s_blink_ph == 2)
    {
      eh = 3;
      ew = base_w + 10;
      lx = 0;
      ly = 0;
    }
  else if (s_blink_ph == 1)
    {
      eh = 7;
    }

  lv_obj_set_size(g_dm_eye_l, ew, eh);
  lv_obj_set_size(g_dm_eye_r, ew, eh);
  lv_obj_set_pos(g_dm_eye_l, size / 2 - size / 4 - ew / 2 + lx,
                 size * 30 / 100 + ly);
  lv_obj_set_pos(g_dm_eye_r, size / 2 + size / 4 - ew / 2 - lx,
                 size * 30 / 100 + ly);

  if (g_dm_mouth)
    {
      int mw = 16;
      int mh = 4;
      switch (s_paint_face)
        {
          case FACE_HAPPY:
          case FACE_DONE:
            mw = 22;
            mh = 5;
            break;
          case FACE_LOVE:
            mw = 18;
            mh = 4;
            break;
          case FACE_SURPRISE:
            mw = 12;
            mh = 12;
            break;
          case FACE_FOCUS:
            mw = 14;
            mh = 3;
            break;
          default:
            break;
        }
      lv_obj_set_size(g_dm_mouth, mw, mh);
      lv_obj_set_pos(g_dm_mouth, size / 2 - mw / 2, size * 62 / 100);
    }

  if (!g_dm_decor_l || !g_dm_decor_r)
    {
      return;
    }

  if (g_dm.decor == EYE_DECOR_NONE || s_blink_ph == 2)
    {
      lv_obj_set_style_bg_opa(g_dm_decor_l, LV_OPA_TRANSP, LV_PART_MAIN);
      lv_obj_set_style_bg_opa(g_dm_decor_r, LV_OPA_TRANSP, LV_PART_MAIN);
      return;
    }

  uint32_t col = C_STAR;
  int d = 8;
  if (g_dm.decor == EYE_DECOR_HEART)
    {
      col = C_HEART;
      d = 9;
    }
  else if (g_dm.decor == EYE_DECOR_WIDE)
    {
      col = C_ACCENT;
      d = 6;
    }

  lv_obj_set_style_bg_color(g_dm_decor_l, lv_color_hex(col), LV_PART_MAIN);
  lv_obj_set_style_bg_color(g_dm_decor_r, lv_color_hex(col), LV_PART_MAIN);
  lv_obj_set_size(g_dm_decor_l, d, d);
  lv_obj_set_size(g_dm_decor_r, d, d);
  lv_obj_set_style_bg_opa(g_dm_decor_l, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_bg_opa(g_dm_decor_r, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_pos(g_dm_decor_l, size * 20 / 100, size * 20 / 100);
  lv_obj_set_pos(g_dm_decor_r, size * 72 / 100, size * 20 / 100);
}

void dm_face_tick(void)
{
  if (!g_dm_face)
    {
      return;
    }

  s_idle_t++;

  if (s_blink_hold > 0)
    {
      s_blink_hold--;
    }
  else if (s_blink_ph == 0)
    {
      if (s_blink_gap > 0)
        {
          s_blink_gap--;
        }
      else
        {
          s_blink_ph = 1;
          s_blink_hold = 1;
        }
    }
  else if (s_blink_ph == 1)
    {
      s_blink_ph = 2;
      s_blink_hold = 1;
    }
  else
    {
      s_blink_ph = 0;
      s_blink_hold = 0;
      s_blink_gap = 6 + (s_idle_t % 10);
    }

  if (g_dm.decor_hold > 0)
    {
      g_dm.decor_hold--;
      if (g_dm.decor_hold == 0 && g_dm.page == PAGE_FOCUS_RUN &&
          g_dm.focus_run)
        {
          g_dm.decor = EYE_DECOR_NONE;
          dm_face_set(FACE_FOCUS, EYE_DECOR_NONE, 0);
        }
    }

  if (g_dm.wide_hold > 0)
    {
      g_dm.wide_hold--;
    }

  if (s_idle_t % 6 == 0)
    {
      g_dm.look_x = ((s_idle_t / 6) % 5) - 2;
      g_dm.look_y = ((s_idle_t / 9) % 3) - 1;
    }

  if (g_dm.page == PAGE_FOCUS_RUN && g_dm.focus_run && !g_dm.focus_finished &&
      g_dm.decor == EYE_DECOR_NONE && s_idle_t % 28 == 0)
    {
      int pick = (s_idle_t / 28) % 3;
      if (pick == 0)
        {
          dm_face_set(FACE_FOCUS, EYE_DECOR_STAR, 8);
          dm_say("星星眼，状态不错", "Sparkle eyes — nice pace");
        }
      else if (pick == 1)
        {
          dm_face_set(FACE_LOVE, EYE_DECOR_HEART, 8);
          dm_say("给你比个心，继续", "Heart eyes — keep going");
        }
      else
        {
          dm_face_set(FACE_SURPRISE, EYE_DECOR_WIDE, 6);
          dm_say("睁大眼睛看着你", "Watching you — stay with it");
        }
    }

  paint();
}

static const char *s_clicks_zh[] = {
  "我在呢，专注就好",
  "别走神，我帮你看着时间",
  "深呼吸，再坚持一下",
  "点我也没用，倒计时不会停哦",
  "你认真起来还挺好看的",
};
static const char *s_clicks_en[] = {
  "I'm here. Just focus.",
  "Eyes on the task — I'll watch the clock.",
  "Breathe. One more push.",
  "Tapping me won't pause time.",
  "You look focused. Nice.",
};
static int s_click_idx;

void dm_face_on_click(lv_event_t *e)
{
  (void)e;

  if (g_dm.page == PAGE_FOCUS_RUN)
    {
      dm_say(s_clicks_zh[s_click_idx], s_clicks_en[s_click_idx]);
      s_click_idx = (s_click_idx + 1) % 5;
      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 4);
    }
  else
    {
      dm_say("嗨，我是 Deskmate", "Hi, I'm Deskmate");
      dm_face_set(FACE_HAPPY, EYE_DECOR_STAR, 4);
    }
}

#endif /* CONFIG_DESKMATE_APP */

