  { ssid: 'MiFi_8821', sig: 1, lock: true },
  { ssid: 'Guest', sig: 2, lock: false },
];
let selected = null;
let connected = null;

const $ = id => document.getElementById(id);
function show(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('on'));
  $(id).classList.add('on');
}
function renderList() {
  const el = $('apList');
  el.innerHTML = '';
