      <span class="sig">${'▮'.repeat(ap.sig)}${'▯'.repeat(4-ap.sig)}</span>`;
    d.onclick = () => { selected = i; renderList(); };
    d.ondblclick = () => startConnect(ap);
    el.appendChild(d);
  });
}
function startConnect(ap) {
  selected = APs.indexOf(ap);
  if (ap.lock && !$('pwInput').value) {
    $('pwSsid').textContent = ap.ssid;
    $('kb').classList.add('on');
    show('pPw');
    return;
