/****************************************************************************
 * dm_wifi.c — WiFi backend (wapi + pthread, official NuttX flow)
 *
 * Scan/connect run off the LVGL thread. UI polls dm_wifi_* flags via tick.
 ****************************************************************************/

#include "deskmate.h"

#ifdef CONFIG_DESKMATE_APP

#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <wireless/wapi.h>
#include <netutils/netlib.h>

#define DM_WIFI_IF "wlan0"
#define DM_WIFI_AP_MAX 12

typedef struct
{
  char ssid[33];
  int rssi;
  bool open;
} dm_ap_t;

static pthread_mutex_t s_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile int s_scan_busy;
static volatile int s_conn_busy;
static volatile int s_scan_ready;
static volatile int s_conn_ok;
static volatile int s_conn_fail;
static dm_ap_t s_aps[DM_WIFI_AP_MAX];
static int s_ap_n;
static int s_sel = -1;
static char s_cur_ssid[33];
static char s_cur_ip[24];
static char s_pending_ssid[33];
static char s_pending_pass[64];
static bool s_pending_open;
static bool s_wifi_up;

const char *dm_wifi_cur_ssid(void)
{
  return s_cur_ssid[0] ? s_cur_ssid : "";
}

const char *dm_wifi_cur_ip(void)
{
  return s_cur_ip[0] ? s_cur_ip : "";
}

int dm_wifi_connected(void)
{
  return s_cur_ssid[0] ? 1 : 0;
}

int dm_wifi_ap_count(void)
{
  return s_ap_n;
}

int dm_wifi_ap_get(int i, const char **ssid, int *rssi, bool *open)
{
  if (i < 0 || i >= s_ap_n)
    {
      return -1;
    }
  if (ssid)
    {
      *ssid = s_aps[i].ssid;
    }
  if (rssi)
    {
      *rssi = s_aps[i].rssi;
    }
  if (open)
    {
      *open = s_aps[i].open;
    }
  return 0;
}

int dm_wifi_sel(void)
{
  return s_sel;
}

void dm_wifi_set_sel(int i)
{
  s_sel = i;
}

int dm_wifi_scan_busy(void)
{
  return s_scan_busy;
}

int dm_wifi_scan_ready(void)
{
  return s_scan_ready;
}

void dm_wifi_clear_scan_ready(void)
{
  s_scan_ready = 0;
}

int dm_wifi_conn_busy(void)
{
  return s_conn_busy;
}

int dm_wifi_conn_ok(void)
{
  return s_conn_ok;
}

int dm_wifi_conn_fail(void)
{
  return s_conn_fail;
}

void dm_wifi_clear_conn_flags(void)
{
  s_conn_ok = 0;
  s_conn_fail = 0;
}

static void ensure_iface(int sock)
{
  int up = 0;

  if (!s_wifi_up)
    {
      wapi_set_mode(sock, DM_WIFI_IF, WAPI_MODE_MANAGED);
      wapi_set_ifup(sock, DM_WIFI_IF);
      s_wifi_up = true;
    }
  else
    {
      wapi_get_ifup(sock, DM_WIFI_IF, &up);
    }
}

static void *scan_thread(void *arg)
{
  int sock;
  struct wapi_list_s list;
  struct wapi_scan_info_s *ap;
  int n = 0;
  int ret;
  int wait;

  (void)arg;
  sock = wapi_make_socket();
  if (sock < 0)
    {
      s_scan_busy = 0;
      s_scan_ready = 1;
      return NULL;
    }

  pthread_mutex_lock(&s_lock);
  ensure_iface(sock);
  pthread_mutex_unlock(&s_lock);

  ret = wapi_escan_init(sock, DM_WIFI_IF, IW_SCAN_TYPE_ACTIVE, NULL);
  if (ret < 0)
    {
      close(sock);
      s_scan_busy = 0;
      s_scan_ready = 1;
      return NULL;
    }

  for (wait = 0; wait < 20; wait++)
    {
      usleep(200 * 1000);
      ret = wapi_scan_stat(sock, DM_WIFI_IF);
      if (ret == 0)
        {
          break;
        }
    }

  memset(&list, 0, sizeof(list));
  ret = wapi_scan_coll(sock, DM_WIFI_IF, &list);
  pthread_mutex_lock(&s_lock);
  s_ap_n = 0;
  if (ret >= 0)
    {
      for (ap = list.head.scan; ap && n < DM_WIFI_AP_MAX; ap = ap->next)
        {
          if (!ap->has_essid || ap->essid[0] == 0)
            {
              continue;
            }
          strncpy(s_aps[n].ssid, ap->essid, sizeof(s_aps[n].ssid) - 1);
          s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
          s_aps[n].rssi = ap->has_rssi ? ap->rssi : 0;
          s_aps[n].open = (ap->has_encode == 0) || (ap->encode == 0);
          n++;
        }
      s_ap_n = n;
    }
  pthread_mutex_unlock(&s_lock);

  wapi_scan_coll_free(&list);
  close(sock);
  s_scan_busy = 0;
  s_scan_ready = 1;
  return NULL;
}

int dm_wifi_start_scan(void)
{
  pthread_t th;
  pthread_attr_t attr;
  int ret;

  if (s_scan_busy || s_conn_busy)
    {
      return -1;
    }

  s_scan_ready = 0;
  s_scan_busy = 1;
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 16384);
  ret = pthread_create(&th, &attr, scan_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      s_scan_busy = 0;
      return -1;
    }
  pthread_detach(th);
  return 0;
}

static int set_psk(int sock, const char *pass)
{
  int ret;

  ret = wpa_driver_wext_set_auth_param(sock, DM_WIFI_IF,
                                       IW_AUTH_WPA_VERSION,
                                       IW_AUTH_WPA_VERSION_WPA2);
  if (ret < 0)
    {
      return ret;
    }
  ret = wpa_driver_wext_set_auth_param(sock, DM_WIFI_IF,
                                       IW_AUTH_CIPHER_PAIRWISE,
                                       IW_AUTH_CIPHER_CCMP);
  if (ret < 0)
    {
      return ret;
    }
  return wpa_driver_wext_set_key_ext(sock, DM_WIFI_IF, WPA_ALG_CCMP, pass,
                                     strlen(pass));
}

static void *conn_thread(void *arg)
{
  int sock;
  int ret;
  int i;

  (void)arg;
  sock = wapi_make_socket();
  if (sock < 0)
    {
      s_conn_busy = 0;
      s_conn_fail = 1;
      return NULL;
    }

  pthread_mutex_lock(&s_lock);
  ensure_iface(sock);
  pthread_mutex_unlock(&s_lock);

  if (!s_pending_open && s_pending_pass[0])
    {
      ret = set_psk(sock, s_pending_pass);
      if (ret < 0)
        {
          close(sock);
          s_conn_busy = 0;
          s_conn_fail = 1;
          return NULL;
        }
    }

  ret = wapi_set_essid(sock, DM_WIFI_IF, s_pending_ssid, WAPI_ESSID_ON);
  if (ret < 0)
    {
      close(sock);
      s_conn_busy = 0;
      s_conn_fail = 1;
      return NULL;
    }

  close(sock);

  /* wait link then DHCP (official: renew wlan0) */
  sleep(3);
  ret = netlib_obtain_ipv4addr(DM_WIFI_IF);
  if (ret < 0)
    {
      s_conn_busy = 0;
      s_conn_fail = 1;
      return NULL;
    }

  pthread_mutex_lock(&s_lock);
  strncpy(s_cur_ssid, s_pending_ssid, sizeof(s_cur_ssid) - 1);
  s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
  struct in_addr addr;
  if (netlib_get_ipv4addr(DM_WIFI_IF, &addr) == 0)
    {
      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
    }
  else
    {
      strncpy(s_cur_ip, "0.0.0.0", sizeof(s_cur_ip) - 1);
    }
  pthread_mutex_unlock(&s_lock);

  /* best-effort save for reconnect on boot */
  (void)system("wapi save_config wlan0 > /dev/null 2>&1");

  (void)i;
  s_conn_busy = 0;
  s_conn_ok = 1;
  return NULL;
}

int dm_wifi_connect(const char *ssid, const char *pass)
{
  pthread_t th;
  pthread_attr_t attr;
  int ret;

  if (!ssid || !ssid[0] || s_scan_busy || s_conn_busy)
    {
      return -1;
    }

  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
  if (pass)
    {
      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
    }
  else
    {
      s_pending_pass[0] = 0;
    }
  s_pending_open = (s_pending_pass[0] == 0);

  s_conn_ok = 0;
  s_conn_fail = 0;
  s_conn_busy = 1;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 16384);
  ret = pthread_create(&th, &attr, conn_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      s_conn_busy = 0;
      return -1;
    }
  pthread_detach(th);
  return 0;
}

void dm_wifi_tick(void)
{
  /* reserved for auto-refresh; UI pulls flags in wifi page tick */
}

