  lv_obj_t *bar;
  lv_obj_t *inner;
  int i;
  int w = 54;
  int gap = 8;
  int pad = 8;
  int total = pad * 2 + 6 * w + 5 * gap; /* 380 > 320 → can scroll */

  /* Fixed bar (not scrollable) */
  bar = lv_obj_create(g_dm_root);
  lv_obj_set_size(bar, DM_SCR_W, 46);
  lv_obj_set_pos(bar, 0, DM_SCR_H - 46);
  lv_obj_set_style_bg_color(bar, lv_color_hex(0x080808), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(bar, 0, LV_PART_MAIN);
  lv_obj_set_style_radius(bar, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(bar, 0, LV_PART_MAIN);
  lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_style_clip_corner(bar, true, LV_PART_MAIN);
  g_dm_dock = bar;

  /* Wide inner track — this is what we scroll */
  inner = lv_obj_create(bar);
  lv_obj_set_size(inner, total, 46);
  lv_obj_set_pos(inner, 0, 0);
  lv_obj_set_style_bg_opa(inner, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_style_border_width(inner, 0, LV_PART_MAIN);
  lv_obj_set_style_radius(inner, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(inner, 0, LV_PART_MAIN);
  lv_obj_clear_flag(inner, LV_OBJ_FLAG_SCROLLABLE);

  for (i = 0; i < 6; i++)
    {
      s_dock_btns[i] = dm_btn(inner, zh[i], en[i], w, 32, C_BTN, C_MUTED,
                              dock_cb, (void *)(uintptr_t)s_dock_target[i]);
      lv_obj_set_pos(s_dock_btns[i], pad + i * (w + gap), 7);
    }

  /* Enable horizontal drag on the bar itself */
  lv_obj_add_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_scroll_dir(bar, LV_DIR_HOR);
  lv_obj_set_scrollbar_mode(bar, LV_SCROLLBAR_MODE_OFF);
  lv_obj_set_scroll_momentum(bar, false);

  dm_dock_highlight(PAGE_FOCUS_HOME);
}

