/****************************************************************************
 * dm_ui_word.c — Word Memo board pages (from wordsmemo quickapp)
 *
 * Independent page group under Features hub.
 * Scrollable lists; built-in bank subset; local file progress.
 ****************************************************************************/

#include "deskmate.h"
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>

#ifdef CONFIG_DESKMATE_APP

#define DM_WORD_PATH "/data/deskmate_word.bin"
#define DM_WORD_MAGIC 0x574f5244u /* WORD */
#define DM_WORD_N 20
#define DM_WORD_ROUND 8
#define DM_QUIZ_N 5

typedef struct
{
  const char *en;
  const char *cn;
} word_t;

/* subset inspired by word-bank-a */
static const word_t s_bank[DM_WORD_N] = {
  { "abandon", "giving up" },
  { "accept", "to take" },
  { "achieve", "to finish well" },
  { "bright", "shiny / smart" },
  { "curious", "want to know" },
  { "gentle", "soft / kind" },
  { "journey", "a long trip" },
  { "brave", "not afraid" },
  { "quiet", "no noise" },
  { "quickly", "very fast" },
  { "active", "full of energy" },
  { "advice", "a helpful tip" },
  { "afraid", "scared" },
  { "agree", "say yes" },
  { "airport", "fly from here" },
  { "alone", "by oneself" },
  { "already", "before now" },
  { "always", "every time" },
  { "among", "in the middle of" },
  { "angry", "very mad" },
};

typedef struct
{
  uint32_t magic;
  int32_t learned;
  int32_t wrong_n;
  int32_t daily_goal;
  int32_t weekly_goal;
  uint8_t known[DM_WORD_N];
  uint8_t wrong[DM_WORD_N];
} word_store_t;

static word_store_t s_ws;
static int s_mode_study; /* 0 study 1 review */
static int s_idx;
static int s_flipped;
static int s_k;
static int s_u;
static int s_qi;
static int s_q_correct;
static int s_q_wrong;
static int s_q_ans;
static int s_q_mode; /* 0 en2cn 1 cn2en */
static int s_q_locked;

static lv_obj_t *s_home;
static lv_obj_t *s_study;
static lv_obj_t *s_res;
static lv_obj_t *s_qmode;
static lv_obj_t *s_quiz;
static lv_obj_t *s_wrong;
static lv_obj_t *s_list;
static lv_obj_t *s_wset;
static lv_obj_t *s_n_learn;
static lv_obj_t *s_n_left;
static lv_obj_t *s_prog_tx;
static lv_obj_t *s_s_title;
static lv_obj_t *s_s_prog;
static lv_obj_t *s_w_en;
static lv_obj_t *s_w_cn;
static lv_obj_t *s_r_title;
static lv_obj_t *s_r_a;
static lv_obj_t *s_r_b;
static lv_obj_t *s_r_al;
static lv_obj_t *s_r_bl;
static lv_obj_t *s_r_p;
static lv_obj_t *s_r_msg;
static lv_obj_t *s_q_word;
static lv_obj_t *s_q_sub;
static lv_obj_t *s_q_prog;
static lv_obj_t *s_q_opts[4];
static lv_obj_t *s_q_next;
static lv_obj_t *s_wrong_box;
static lv_obj_t *s_list_box;
static lv_obj_t *s_day_l;
static lv_obj_t *s_week_l;

/* ---------- store ---------- */

static void store_save(void)
{
  int fd;
  s_ws.magic = DM_WORD_MAGIC;
  fd = open(DM_WORD_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0666);
  if (fd >= 0)
    {
      (void)write(fd, &s_ws, sizeof(s_ws));
      close(fd);
    }
}

static void store_load(void)
{
  word_store_t t;
  int fd;
  ssize_t n;

  memset(&s_ws, 0, sizeof(s_ws));
  s_ws.daily_goal = 10;
  s_ws.weekly_goal = 70;
  fd = open(DM_WORD_PATH, O_RDONLY);
  if (fd < 0)
    {
      return;
    }
  n = read(fd, &t, sizeof(t));
  close(fd);
  if (n == (ssize_t)sizeof(t) && t.magic == DM_WORD_MAGIC)
    {
      s_ws = t;
    }
}

static void recount(void)
{
  int i;
  s_ws.learned = 0;
  s_ws.wrong_n = 0;
  for (i = 0; i < DM_WORD_N; i++)
    {
      if (s_ws.known[i])
        {
          s_ws.learned++;
        }
      if (s_ws.wrong[i])
        {
          s_ws.wrong_n++;
        }
    }
}

/* ---------- helpers ---------- */

static lv_obj_t *mk_page(dm_page_t id)
{
  lv_obj_t *page = lv_obj_create(g_dm_root);
  lv_obj_set_size(page, DM_SCR_W, DM_SCR_H);
  lv_obj_set_pos(page, 0, 0);
  lv_obj_set_style_bg_color(page, lv_color_hex(C_BG), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(page, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(page, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(page, 0, LV_PART_MAIN);
  lv_obj_clear_flag(page, LV_OBJ_FLAG_SCROLLABLE);
  g_dm_pages[id] = page;
  return page;
}

static lv_obj_t *sc_body(lv_obj_t *page)
{
  lv_obj_t *sc = lv_obj_create(page);
  lv_obj_set_size(sc, DM_SCR_W, 160);
  lv_obj_set_pos(sc, 0, 28);
  lv_obj_set_style_bg_opa(sc, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_style_border_width(sc, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(sc, 10, LV_PART_MAIN);
  lv_obj_set_style_pad_row(sc, 6, LV_PART_MAIN);
  lv_obj_set_scroll_dir(sc, LV_DIR_VER);
  lv_obj_set_scrollbar_mode(sc, LV_SCROLLBAR_MODE_AUTO);
  lv_obj_set_flex_flow(sc, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(sc, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER);
  return sc;
}

static lv_obj_t *row_card(lv_obj_t *sc, const char *zh, const char *en,
                          const char *hzh, const char *hen, lv_event_cb_t cb,
                          void *ud)
{
  lv_obj_t *c = lv_obj_create(sc);
  lv_obj_t *n;
  lv_obj_t *h;
  lv_obj_t *a;

  lv_obj_set_size(c, 292, 44);
  lv_obj_set_style_bg_color(c, lv_color_hex(0x111111), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(c, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_radius(c, 10, LV_PART_MAIN);
  lv_obj_set_style_border_width(c, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(c, 8, LV_PART_MAIN);
  lv_obj_clear_flag(c, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_flag(c, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_add_event_cb(c, cb, LV_EVENT_CLICKED, ud);

  n = dm_lbl(c, zh, en, g_dm_font_s, C_INK);
  lv_obj_set_pos(n, 0, 2);
  h = dm_lbl(c, hzh, hen, g_dm_font_s, C_MUTED);
  lv_obj_set_pos(h, 0, 20);
  a = dm_lbl(c, ">", ">", g_dm_font_m, C_MUTED);
  lv_obj_align(a, LV_ALIGN_RIGHT_MID, 0, 0);
  return c;
}

static void back_features(lv_event_t *e)
{
  (void)e;
  dm_show(PAGE_FEATURES);
}

static void back_word(lv_event_t *e)
{
  (void)e;
  recount();
  if (s_n_learn)
    {
      char b[24];
      lv_snprintf(b, sizeof(b), "%ld", (long)s_ws.learned);
      lv_label_set_text(s_n_learn, b);
    }
  if (s_n_left)
    {
      char b[24];
      lv_snprintf(b, sizeof(b), "%ld", (long)(DM_WORD_N - s_ws.learned));
      lv_label_set_text(s_n_left, b);
    }
  if (s_prog_tx)
    {
      int p = s_ws.learned * 100 / DM_WORD_N;
      char b[16];
      lv_snprintf(b, sizeof(b), "%d%%", p);
      lv_label_set_text(s_prog_tx, b);
    }
  dm_show(PAGE_WORD_HOME);
}

/* ---------- study ---------- */

static void show_word(void)
{
  const word_t *t;
  if (s_idx < 0)
    {
      s_idx = 0;
    }
  if (s_idx >= DM_WORD_N)
    {
      s_idx = 0;
    }
  t = &s_bank[s_idx];
  if (s_w_en)
    {
      lv_label_set_text(s_w_en, t->en);
    }
  if (s_w_cn)
    {
      lv_label_set_text(s_w_cn, s_flipped ? t->cn : dm_t("点卡片看释义",
                                                         "Tap card for meaning"));
    }
  if (s_s_prog)
    {
      char b[16];
      lv_snprintf(b, sizeof(b), "%d/%d", s_idx + 1, DM_WORD_ROUND);
      lv_label_set_text(s_s_prog, b);
    }
}

static void flip_cb(lv_event_t *e)
{
  (void)e;
  s_flipped = !s_flipped;
  show_word();
}

static void mark_cb(lv_event_t *e)
{
  int known = (int)(uintptr_t)lv_event_get_user_data(e);

  if (known)
    {
      s_k++;
      s_ws.known[s_idx] = 1;
      s_ws.wrong[s_idx] = 0;
    }
  else
    {
      s_u++;
      s_ws.wrong[s_idx] = 1;
    }
  s_idx++;
  s_flipped = 0;
  if (s_idx >= DM_WORD_ROUND)
    {
      char b[12];
      int p;
      recount();
      store_save();
      if (s_r_title)
        {
          lv_label_set_text(s_r_title,
                            s_mode_study ? dm_t("复习完成", "Review done")
                                         : dm_t("学习完成", "Study done"));
        }
      if (s_r_al)
        {
          lv_label_set_text(s_r_al, dm_t("认识", "Know"));
        }
      if (s_r_bl)
        {
          lv_label_set_text(s_r_bl, dm_t("不认识", "Unknown"));
        }
      if (s_r_a)
        {
          lv_snprintf(b, sizeof(b), "%d", s_k);
          lv_label_set_text(s_r_a, b);
        }
      if (s_r_b)
        {
          lv_snprintf(b, sizeof(b), "%d", s_u);
          lv_label_set_text(s_r_b, b);
        }
      p = (s_k + s_u) ? (s_k * 100 / (s_k + s_u)) : 0;
      if (s_r_p)
        {
          lv_snprintf(b, sizeof(b), "%d%%", p);
          lv_label_set_text(s_r_p, b);
        }
      if (s_r_msg)
        {
          lv_label_set_text(s_r_msg,
                            p >= 90 ? dm_t("太棒了！", "Awesome!")
                                    : (p >= 70 ? dm_t("不错，继续",
                                                      "Nice, keep going")
                                               : dm_t("再巩固一下",
                                                      "Review the hard ones")));
        }
      dm_show(PAGE_WORD_RES);
      return;
    }
  show_word();
}

static void start_study(int review)
{
  s_mode_study = review;
  s_idx = 0;
  s_flipped = 0;
  s_k = 0;
  s_u = 0;
  if (s_s_title)
    {
      lv_label_set_text(s_s_title,
                        review ? dm_t("复习", "Review") : dm_t("学习", "Study"));
    }
  show_word();
  dm_show(PAGE_WORD_STUDY);
}

static void start_study_cb(lv_event_t *e)
{
  (void)e;
  start_study(0);
}

static void start_review_cb(lv_event_t *e)
{
  (void)e;
  start_study(1);
}

/* ---------- quiz ---------- */

static void show_quiz(void)
{
  const word_t *t = &s_bank[s_qi % DM_WORD_N];
  char opts[4][24];
  int order[4];
  int i;
  int j;

  s_q_locked = 0;
  if (s_q_next)
    {
      lv_obj_add_flag(s_q_next, LV_OBJ_FLAG_HIDDEN);
    }
  if (s_q_prog)
    {
      char b[12];
      lv_snprintf(b, sizeof(b), "%d/%d", s_qi + 1, DM_QUIZ_N);
      lv_label_set_text(s_q_prog, b);
    }

  if (s_q_mode == 0)
    {
      if (s_q_word)
        {
          lv_label_set_text(s_q_word, t->en);
        }
      if (s_q_sub)
        {
          lv_label_set_text(s_q_sub, dm_t("选择正确释义", "Pick meaning"));
        }
      strncpy(opts[0], t->cn, 23);
    }
  else
    {
      if (s_q_word)
        {
          lv_label_set_text(s_q_word, t->cn);
        }
      if (s_q_sub)
        {
          lv_label_set_text(s_q_sub, dm_t("选择正确单词", "Pick word"));
        }
      strncpy(opts[0], t->en, 23);
    }
  opts[0][23] = 0;

  for (i = 1; i < 4; i++)
    {
      int n = (s_qi * 3 + i * 5) % DM_WORD_N;
      if (n == s_qi % DM_WORD_N)
        {
          n = (n + 1) % DM_WORD_N;
        }
      strncpy(opts[i],
              s_q_mode == 0 ? s_bank[n].cn : s_bank[n].en, 23);
      opts[i][23] = 0;
    }

  /* shuffle: rotate */
  for (i = 0; i < 4; i++)
    {
      order[i] = i;
    }
  j = s_qi % 4;
  for (i = 0; i < 4; i++)
    {
      int tmp = order[i];
      order[i] = order[(i + j) % 4];
      order[(i + j) % 4] = tmp;
    }
  s_q_ans = 0;
  for (i = 0; i < 4; i++)
    {
      if (order[i] == 0)
        {
          s_q_ans = i;
        }
    }

  for (i = 0; i < 4; i++)
    {
      if (s_q_opts[i])
        {
          lv_obj_t *lab = lv_obj_get_child(s_q_opts[i], 0);
          lv_obj_set_style_bg_color(s_q_opts[i], lv_color_hex(C_BTN_HI),
                                    LV_PART_MAIN);
          if (lab)
            {
              lv_obj_set_style_text_color(lab, lv_color_hex(C_INK),
                                          LV_PART_MAIN);
              lv_label_set_text(lab, opts[order[i]]);
            }
        }
    }
}

static void q_opt_cb(lv_event_t *e)
{
  int i;
  int pick = (int)(uintptr_t)lv_event_get_user_data(e);

  if (s_q_locked)
    {
      return;
    }
  s_q_locked = 1;
  for (i = 0; i < 4; i++)
    {
      lv_obj_t *lab;
      uint32_t bg = C_BTN_HI;
      uint32_t fg = C_INK;
      if (i == s_q_ans)
        {
          bg = C_OK;
          fg = C_EYE;
        }
      else if (i == pick)
        {
          bg = C_HEART;
          fg = C_EYE;
        }
      if (s_q_opts[i])
        {
          lv_obj_set_style_bg_color(s_q_opts[i], lv_color_hex(bg),
                                    LV_PART_MAIN);
          lab = lv_obj_get_child(s_q_opts[i], 0);
          if (lab)
            {
              lv_obj_set_style_text_color(lab, lv_color_hex(fg),
                                          LV_PART_MAIN);
            }
        }
    }
  if (pick == s_q_ans)
    {
      s_q_correct++;
      s_ws.known[s_qi % DM_WORD_N] = 1;
    }
  else
    {
      s_q_wrong++;
      s_ws.wrong[s_qi % DM_WORD_N] = 1;
    }
  if (s_q_next)
    {
      lv_obj_clear_flag(s_q_next, LV_OBJ_FLAG_HIDDEN);
    }
}

static void q_next_cb(lv_event_t *e)
{
  char b[12];
  int p;
  (void)e;

  s_qi++;
  if (s_qi < DM_QUIZ_N)
    {
      show_quiz();
      return;
    }
  recount();
  store_save();
  if (s_r_title)
    {
      lv_label_set_text(s_r_title, dm_t("测验完成", "Quiz done"));
    }
  if (s_r_al)
    {
      lv_label_set_text(s_r_al, dm_t("正确", "Correct"));
    }
  if (s_r_bl)
    {
      lv_label_set_text(s_r_bl, dm_t("错误", "Wrong"));
    }
  if (s_r_a)
    {
      lv_snprintf(b, sizeof(b), "%d", s_q_correct);
      lv_label_set_text(s_r_a, b);
    }
  if (s_r_b)
    {
      lv_snprintf(b, sizeof(b), "%d", s_q_wrong);
      lv_label_set_text(s_r_b, b);
    }
  p = s_q_correct * 100 / DM_QUIZ_N;
  if (s_r_p)
    {
      lv_snprintf(b, sizeof(b), "%d%%", p);
      lv_label_set_text(s_r_p, b);
    }
  if (s_r_msg)
    {
      lv_label_set_text(s_r_msg,
                        s_q_correct >= 4 ? dm_t("成绩很好！", "Great score!")
                                         : dm_t("错词会进错题本",
                                                "Mistakes go to wrong book"));
    }
  dm_show(PAGE_WORD_RES);
}

static void q_mode_cb(lv_event_t *e)
{
  s_q_mode = (int)(uintptr_t)lv_event_get_user_data(e);
  s_qi = 0;
  s_q_correct = 0;
  s_q_wrong = 0;
  show_quiz();
  dm_show(PAGE_WORD_QUIZ);
}

/* ---------- build ---------- */

void dm_create_word(void)
{
  lv_obj_t *title;
  lv_obj_t *sc;
  int i;

  store_load();

  /* ---- home ---- */
  s_home = mk_page(PAGE_WORD_HOME);
  title = dm_lbl(s_home, "背单词", "Word Memo", g_dm_font_m, C_INK);
  lv_obj_set_pos(title, 48, 10);
  {
    lv_obj_t *b = dm_btn(s_home, "←", "<", 36, 24, C_BTN, C_MUTED,
                         back_features, NULL);
    lv_obj_set_pos(b, 8, 8);
  }

  sc = sc_body(s_home);
  {
    lv_obj_t *card = lv_obj_create(sc);
    lv_obj_set_size(card, 292, 86);
    lv_obj_set_style_bg_color(card, lv_color_hex(0x111111), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(card, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_radius(card, 12, LV_PART_MAIN);
    lv_obj_set_style_border_width(card, 0, LV_PART_MAIN);
    lv_obj_set_style_pad_all(card, 10, LV_PART_MAIN);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
    {
      lv_obj_t *h = dm_lbl(card, "学习进度", "Progress", g_dm_font_s,
                           C_MUTED);
      lv_obj_set_pos(h, 0, 0);
      s_n_learn = dm_lbl(card, "0", "0", g_dm_font_l, C_INK);
