static void store_save(void)
{
  int fd = open(DM_WORD_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0666);
  s_ws.magic = DM_WORD_MAGIC;
  if (fd >= 0)
    {
      (void)write(fd, &s_ws, sizeof(s_ws));
      close(fd);
    }
}

static void store_load(void)
{
  int fd;
  word_store_t t;

  memset(&s_ws, 0, sizeof(s_ws));
  s_ws.daily_goal = 10;
  fd = open(DM_WORD_PATH, O_RDONLY);
  if (fd < 0)
    {
      return;
    }
  if (read(fd, &t, sizeof(t)) == (ssize_t)sizeof(t) && t.magic == DM_WORD_MAGIC)
    {
      s_ws = t;
    }
  close(fd);
}

static void recount(void)
{
  int i;
  s_ws.learned = 0;
  s_ws.wrong_n = 0;
  for (i = 0; i < DM_WORD_N; i++)
    {
      if (s_ws.known[i])
        {
          s_ws.learned++;
        }
      if (s_ws.wrong[i])
        {
          s_ws.wrong_n++;
        }
    }
}

