static void show_card(void)
{
  char b[16];
  if (s_idx < 0 || s_idx >= DM_WORD_N)
    {
      s_idx = 0;
    }
  if (s_w_en)
    {
      lv_label_set_text(s_w_en, s_bank[s_idx].en);
    }
  if (s_w_cn)
    {
      lv_label_set_text(
          s_w_cn,
          s_flip ? s_bank[s_idx].cn : dm_t("点卡片看释义", "Tap for meaning"));
    }
  if (s_s_prog)
    {
      lv_snprintf(b, sizeof(b), "%d/%d", s_idx + 1, DM_ROUND);
      lv_label_set_text(s_s_prog, b);
    }
}

