/****************************************************************************
 * dm_ui_tools.c — Calculator / Sensors / Guess / Convert
 ****************************************************************************/

#include "deskmate.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <nuttx/uorb.h>

#ifdef CONFIG_DESKMATE_APP

/* ---------- shared shell ---------- */

static lv_obj_t *mk_tools_page(dm_page_t id, const char *zh, const char *en)
{
