}

/* ---------- calculator ---------- */

#define CALC_EXPR_MAX 48
#define CALC_CUR_MAX 16

static lv_obj_t *s_calc_expr_l;
static lv_obj_t *s_calc_res_l;
static char s_calc_expr[CALC_EXPR_MAX];
static char s_calc_cur[CALC_CUR_MAX];
static bool s_calc_just_eq;
static double s_calc_acc;
static char s_calc_op; /* 0 none, else + - * / */
static bool s_calc_typing;

static void calc_show(void)
{
  if (s_calc_expr_l)
    {
      lv_label_set_text(s_calc_expr_l, s_calc_expr[0] ? s_calc_expr : " ");
    }
  if (s_calc_res_l)
    {
      lv_label_set_text(s_calc_res_l, s_calc_cur);
    }
}

static void calc_fmt_num(double v, char *out, size_t n)
{
  if (!isfinite(v))
    {
      snprintf(out, n, "ERR");
      return;
    }
  if (fabs(v) >= 1e10 || (fabs(v) < 1e-6 && v != 0.0))
    {
      snprintf(out, n, "%.6g", v);
    }
  else
    {
      snprintf(out, n, "%.10g", v);
    }
}

static double calc_apply(double a, char op, double b)
{
  switch (op)
    {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '*':
      return a * b;
    case '/':
      return b == 0.0 ? NAN : a / b;
    default:
      return b;
    }
}

static void calc_reset(void)
{
  s_calc_expr[0] = 0;
  snprintf(s_calc_cur, sizeof(s_calc_cur), "0");
  s_calc_just_eq = false;
  s_calc_acc = 0;
  s_calc_op = 0;
  s_calc_typing = false;
  calc_show();
}

static void calc_digit(char c)
{
  size_t len;

  if (s_calc_just_eq)
    {
      s_calc_expr[0] = 0;
      s_calc_acc = 0;
      s_calc_op = 0;
      s_calc_just_eq = false;
      s_calc_typing = false;
    }
  if (!s_calc_typing || strcmp(s_calc_cur, "0") == 0)
    {
      if (c == '.')
        {
          snprintf(s_calc_cur, sizeof(s_calc_cur), "0.");
        }
      else
        {
          s_calc_cur[0] = c;
          s_calc_cur[1] = 0;
        }
      s_calc_typing = true;
    }
  else
    {
      len = strlen(s_calc_cur);
      if (c == '.' && strchr(s_calc_cur, '.'))
        {
          return;
        }
      if (len + 1 < sizeof(s_calc_cur))
        {
          s_calc_cur[len] = c;
          s_calc_cur[len + 1] = 0;
        }
    }
  calc_show();
}

static void calc_op(char op)
{
  double cur;

  if (s_calc_just_eq)
    {
      /* keep result as left operand */
      s_calc_expr[0] = 0;
      snprintf(s_calc_expr, sizeof(s_calc_expr), "%s", s_calc_cur);
      s_calc_acc = atof(s_calc_cur);
      s_calc_just_eq = false;
    }
  else if (!s_calc_typing && s_calc_op == 0)
    {
      snprintf(s_calc_expr, sizeof(s_calc_expr), "%s", s_calc_cur);
      s_calc_acc = atof(s_calc_cur);
    }
  else if (s_calc_typing || s_calc_op)
    {
      cur = atof(s_calc_cur);
      if (s_calc_op)
        {
          s_calc_acc = calc_apply(s_calc_acc, s_calc_op, cur);
          calc_fmt_num(s_calc_acc, s_calc_cur, sizeof(s_calc_cur));
        }
      else
        {
          s_calc_acc = cur;
        }
      if (strlen(s_calc_expr) + 4 < sizeof(s_calc_expr))
        {
          size_t n = strlen(s_calc_expr);
          snprintf(s_calc_expr + n, sizeof(s_calc_expr) - n, " %c", op);
        }
    }

  s_calc_op = op;
  s_calc_typing = false;
  if (s_calc_expr[0] == 0)
    {
      snprintf(s_calc_expr, sizeof(s_calc_expr), "%s %c", s_calc_cur, op);
    }
  else if (s_calc_expr[strlen(s_calc_expr) - 1] != op &&
           strchr("+-*/", s_calc_expr[strlen(s_calc_expr) - 1]))
    {
      /* replace trailing op */
      size_t n = strlen(s_calc_expr);
      s_calc_expr[n - 1] = op;
    }
  else if (!strchr("+-*/", s_calc_expr[strlen(s_calc_expr) - 1]) &&
           strlen(s_calc_expr) + 3 < sizeof(s_calc_expr))
    {
      size_t n = strlen(s_calc_expr);
      snprintf(s_calc_expr + n, sizeof(s_calc_expr) - n, " %c", op);
    }
  calc_show();
}

static void calc_eval(void)
{
  double cur;
  double r;

  if (!s_calc_op)
    {
      s_calc_just_eq = true;
      return;
    }
  cur = atof(s_calc_cur);
  r = calc_apply(s_calc_acc, s_calc_op, cur);
  calc_fmt_num(r, s_calc_cur, sizeof(s_calc_cur));
  {
    size_t n = strlen(s_calc_expr);
    snprintf(s_calc_expr + n, sizeof(s_calc_expr) - n, " %s =", s_calc_cur);
  }
  s_calc_acc = r;
  s_calc_op = 0;
  s_calc_typing = false;
  s_calc_just_eq = true;
  calc_show();
}

static void calc_back(void)
{
  size_t n;

  if (s_calc_just_eq)
    {
      calc_reset();
      return;
    }
  n = strlen(s_calc_cur);
  if (n > 1)
    {
      s_calc_cur[n - 1] = 0;
    }
  else
    {
      snprintf(s_calc_cur, sizeof(s_calc_cur), "0");
      s_calc_typing = false;
    }
  calc_show();
}

static void calc_sign(void)
{
  if (s_calc_cur[0] == '-')
    {
      memmove(s_calc_cur, s_calc_cur + 1, strlen(s_calc_cur));
    }
  else if (strcmp(s_calc_cur, "0") != 0)
    {
      char tmp[CALC_CUR_MAX];
      snprintf(tmp, sizeof(tmp), "-%s", s_calc_cur);
      snprintf(s_calc_cur, sizeof(s_calc_cur), "%s", tmp);
    }
  calc_show();
}

static void calc_key_cb(lv_event_t *e)
{
  const char *k = (const char *)lv_event_get_user_data(e);
  if (!k || !k[0])
    {
      return;
    }
  if (strcmp(k, "C") == 0)
    {
      calc_reset();
    }
  else if (strcmp(k, "BS") == 0)
    {
      calc_back();
    }
  else if (strcmp(k, "SG") == 0)
    {
      calc_sign();
    }
  else if (strcmp(k, "=") == 0)
    {
      calc_eval();
    }
  else if (k[1] == 0 && strchr("+-*/", k[0]))
    {
      calc_op(k[0]);
    }
  else if (k[1] == 0 && (k[0] == '.' || (k[0] >= '0' && k[0] <= '9')))
    {
      calc_digit(k[0]);
    }
}

static void mk_calc_btn(lv_obj_t *p, const char *text, const char *ud,
                        int x, int y, int w, int h, uint32_t bg, uint32_t fg)
{
  lv_obj_t *b = lv_button_create(p);
  lv_obj_t *t;

  lv_obj_set_size(b, w, h);
  lv_obj_set_pos(b, x, y);
  lv_obj_set_style_radius(b, 10, LV_PART_MAIN);
  lv_obj_set_style_bg_color(b, lv_color_hex(bg), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(b, 0, LV_PART_MAIN);
  lv_obj_set_style_shadow_width(b, 0, LV_PART_MAIN);
  lv_obj_add_flag(b, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_clear_flag(b, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_event_cb(b, calc_key_cb, LV_EVENT_CLICKED, (void *)(uintptr_t)ud);

  t = dm_lbl(b, text, text, g_dm_font_s, fg);
  lv_obj_center(t);
  lv_obj_clear_flag(t, LV_OBJ_FLAG_CLICKABLE);
}

void dm_create_calc(void)
{
  lv_obj_t *page = mk_tools_page2(PAGE_CALC, "计算器", "Calc");
  lv_obj_t *disp;
  int row_y[5] = { 52, 88, 124, 160, 196 };
  int col_x[4] = { 8, 86, 164, 242 };
  int bw = 70;
  int bh = 30;
  int i;
  static const char *keys[5][4] = {
    { "C", "BS", "SG", "/" },
    { "7", "8", "9", "*" },
    { "4", "5", "6", "-" },
    { "1", "2", "3", "+" },
    { "0", ".", "=", NULL },
