static lv_obj_t *s_sen_t;
static lv_obj_t *s_sen_h;
static lv_obj_t *s_sen_l;
static int s_sen_cnt;

static int sen_read_one(const char *path, size_t sz, float *out)
{
  int fd;
  ssize_t n;
  unsigned char buf[64];

  if (sz > sizeof(buf))
    {
      return -1;
    }
  fd = open(path, O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      return -1;
    }
  n = read(fd, buf, sz);
  close(fd);
  if (n != (ssize_t)sz)
    {
      return -1;
    }
  memcpy(out, buf + sizeof(uint64_t), sizeof(float));
  return 0;
}

static void sen_set(lv_obj_t *lbl, const char *ok, int ok_len)
{
  if (!lbl)
    {
      return;
    }
  if (ok)
    {
      char tmp[32];
      snprintf(tmp, sizeof(tmp), "%.*s", ok_len, ok);
      lv_label_set_text(lbl, tmp);
      lv_obj_set_style_text_color(lbl, lv_color_hex(C_ACCENT), LV_PART_MAIN);
    }
  else
    {
      lv_label_set_text(lbl, "未检测到");
      lv_obj_set_style_text_color(lbl, lv_color_hex(0x444444), LV_PART_MAIN);
    }
}

static void sen_refresh(void)
{
  char tbuf[24];
  char hbuf[24];
  char lbuf[24];
  float tv = 0;
  float hv = 0;
  float lv = 0;
  int ok_t;
  int ok_h;
  int ok_l;

  ok_t = sen_read_one("/dev/sensor/temp0", sizeof(struct sensor_temp), &tv);
  ok_h = sen_read_one("/dev/sensor/humi0", sizeof(struct sensor_humi), &hv);
  ok_l = sen_read_one("/dev/sensor/light0", sizeof(struct sensor_light), &lv);

  if (ok_t == 0)
    {
      snprintf(tbuf, sizeof(tbuf), "%.1f °C", (double)tv);
      sen_set(s_sen_t, tbuf, (int)strlen(tbuf));
    }
  else
    {
      sen_set(s_sen_t, NULL, 0);
    }
  if (ok_h == 0)
    {
      snprintf(hbuf, sizeof(hbuf), "%.0f %%", (double)hv);
      sen_set(s_sen_h, hbuf, (int)strlen(hbuf));
    }
  else
    {
      sen_set(s_sen_h, NULL, 0);
    }
  if (ok_l == 0)
    {
      snprintf(lbuf, sizeof(lbuf), "%.0f lx", (double)lv);
      sen_set(s_sen_l, lbuf, (int)strlen(lbuf));
    }
  else
    {
      sen_set(s_sen_l, NULL, 0);
    }
}

static void sen_refresh_cb(lv_event_t *e)
{
  (void)e;
  sen_refresh();
}

