  int iv = 45;
  int left = 45 * 60;
  int day = today_yday();

  if (f)
    {
      if (fscanf(f, "%d %d %d %d", &c, &iv, &left, &day) != 4)
        {
          day = today_yday();
        }
      fclose(f);
    }
  if (day != today_yday())
    {
      c = 0;
      left = iv * 60;
    }
  if (iv != 30 && iv != 45 && iv != 60 && iv != 90)
    {
      iv = 45;
    }
  s_w_cups = c;
  s_w_interval = iv;
  s_w_left = left > 0 ? left : iv * 60;
  s_w_day = today_yday();
}

static void water_paint(void)
{
  char buf[32];
  int m;
  int s;
  int i;

  if (s_w_big)
    {
      snprintf(buf, sizeof(buf), "%d / %d", s_w_cups, WATER_GOAL);
      lv_label_set_text(s_w_big, buf);
    }
  m = s_w_left / 60;
  s = s_w_left % 60;
  if (s_w_next)
    {
      snprintf(buf, sizeof(buf), "下次提醒 %02d:%02d", m, s);
      lv_label_set_text(s_w_next, buf);
    }
  for (i = 0; i < 4; i++)
    {
      if (!s_w_chips[i])
        {
          continue;
        }
      lv_obj_set_style_bg_color(
          s_w_chips[i],
          lv_color_hex((i == 0 && s_w_interval == 30) ||
                               (i == 1 && s_w_interval == 45) ||
                               (i == 2 && s_w_interval == 60) ||
                               (i == 3 && s_w_interval == 90)
                           ? C_STAR
                           : C_BTN),
          LV_PART_MAIN);
      lv_obj_set_style_text_color(
          lv_obj_get_child(s_w_chips[i], 0),
          lv_color_hex((i == 0 && s_w_interval == 30) ||
                               (i == 1 && s_w_interval == 45) ||
                               (i == 2 && s_w_interval == 60) ||
                               (i == 3 && s_w_interval == 90)
                           ? C_EYE
                           : C_DIM),
          LV_PART_MAIN);
    }
}

static void water_chip_cb(lv_event_t *e)
{
  int iv = (int)(intptr_t)lv_event_get_user_data(e);
