void dm_water_tick(void)
{
  time_t now = time(NULL);
  int left;

  if (s_w_day != today_yday())
    {
      s_w_cups = 0;
      s_w_day = today_yday();
      s_w_due = now + s_w_interval * 60;
      water_save();
    }

  left = (int)(s_w_due - now);
  if (left < 0)
    {
      left = 0;
    }
  if (left != s_w_left)
    {
      s_w_left = left;
      if (g_dm.page == PAGE_WATER)
        {
          if (s_w_tip && s_w_left == 0)
